/* -----------------------------
   utils
----------------------------- */
function slugify(s) {
  return String(s || "")
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

function pickErr(e, fallback = "Something went wrong") {
  return (
    e?.response?.data?.error ||
    e?.response?.data?.message ||
    e?.message ||
    fallback
  );
}

function isObj(v) {
  return !!v && typeof v === "object" && !Array.isArray(v);
}

function isTwoColsLayout(layout) {
  // Accept legacy/label values (e.g. "Two Columns") and stored keys (e.g. "two_columns", "twoCols", "two_cols").
  const raw =
    layout && typeof layout === "object"
      ? (layout.value ??
        layout.layout ??
        layout.key ??
        layout.id ??
        layout.label)
      : layout;

  const s = String(raw || "")
    .trim()
    .toLowerCase();
  if (!s) return false;

  // Normalize: remove non-alphanumerics (spaces/underscores/hyphens)
  const norm = s.replace(/[^a-z0-9]+/g, "");
  return (
    norm === "twocolumns" ||
    norm === "twocolumn" ||
    norm === "twocols" ||
    norm === "twocol" ||
    norm === "2columns" ||
    norm === "2column" ||
    norm === "2cols" ||
    norm === "2col" ||
    norm.includes("twocol")
  );
}

function pagePreviewUrl(slug) {
  const s = String(slug || "").toLowerCase();
  // HashRouter-safe preview URL (keeps basename like /bishoprobertsontv-app)
  const base = (window.location.pathname || "").replace(/\/$/, "");
  const hashPath = s === "home" ? "/" : `/p/${s}`;
  // HashRouter routes are after "#"
  return `${base}#${hashPath}`;
}

function uid() {
  return `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}
/* -----------------------------
   stable stringify for dirty-check
----------------------------- */
function stableStringify(value) {
  const seen = new WeakSet();
  const sorter = (v) => {
    if (!v || typeof v !== "object") return v;
    if (seen.has(v)) return null;
    seen.add(v);
    if (Array.isArray(v)) return v.map(sorter);
    const out = {};
    Object.keys(v)
      .sort()
      .forEach((k) => {
        out[k] = sorter(v[k]);
      });
    return out;
  };
  try {
    return JSON.stringify(sorter(value));
  } catch (_e) {
    try {
      return JSON.stringify(value);
    } catch (_e2) {
      return String(value);
    }
  }
}

/* Helper for hero preview */
function absUrl(u) {
  if (!u) return null;
  if (/^https?:\/\//i.test(u)) return u;
  const base = (api?.defaults?.baseURL || "").replace(/\/api\/?$/i, "");
  return u.startsWith("/") ? `${base}${u}` : `${base}/${u}`;
}

function clampNum(n, min, max) {
  const v = Number(n);
  if (Number.isNaN(v)) return min;
  return Math.max(min, Math.min(max, v));
}

function clamp(n, min, max) {
  n = Number(n) || 0;
  return Math.max(min, Math.min(max, n));
}

